return{winter,setSky(top,bottom,hour){skyUniforms.uTop.value.copy(top);skyUniforms.uBottom.value.copy(bottom);skyUniforms.uTint.value.setScalar(hour>7&&hour<18?.03:.15);},markers,interactive:[...winter.interactive,...gateArms,...archipelago.strings,...targets],occluders,appearance(color){skyUniforms.uTint.value.copy(color);},experiment(detail){if(detail.kind==='bridge')gateArms.forEach((g,i)=>{const open=i===0?detail.key&&detail.lantern:i===1?detail.key||detail.lantern:!detail.key&&!detail.lantern;g.rotation.z=open?Math.PI/2:0;g.material=open?cream:gold;});if(detail.kind==='coin')coinPulse=1;},update(t,still){winter.update(t,still);if(still)return;archipelago.update(t);wheel.rotation.z=t*.06;gondolas.forEach(g=>g.rotation.z=-wheel.rotation.z);spinning.rotation.y=t*.12;seats.forEach((seat,i)=>seat.position.y=1.5+Math.sin(t*1.1+i)*.24);lanterns.forEach(({g,y,phase})=>g.position.y=y+Math.sin(t*.4+phase)*.2);waterUniforms.uTime.value=t;skyUniforms.uTime.value=t;for(let i=0;i<fireCount;i++){const f=fireSeeds[i];fireData[i*3]=f.x+Math.sin(t*.3+f.p)*.4;fireData[i*3+1]=f.y+Math.sin(t*.8+f.p)*.25;fireData[i*3+2]=f.z+Math.cos(t*.4+f.p)*.4;}fireGeo.attributes.position.needsUpdate=true;}};
